B2 = pd.read_csv(f"{I}/B2_duplicate_bodyweight_trajectories_real_values.csv")
def dup(a_block, a_group, b_block, b_group):
    q = B2[(B2.a_block == a_block) & (B2.a_group == a_group) & (B2.b_block == b_block) & (B2.b_group == b_group)]
    return len(q), int(q.n_identical.sum()), int(q.n_common.sum())
